INSERT INTO knowledge_base (content, source, source_type, metadata, embedding) VALUES
(
    'Developed GraphSAGE (Graph Sample and Aggregate — a graph neural network that generates embeddings by sampling and aggregating features from a node''s local neighborhood) and Node2Vec (learns node embeddings via biased random walks on the graph) pipelines — best model (PSN+GraphSAGE) achieved 83.5% accuracy, 0.913 AUC-ROC, 0.827 F1, and 0.860 Recall with Nested Cross-Validation (Graph Learning for Heart Disease Prediction, graduate project).',
    'graph_learning_project',
    'project',
    '{"project": "Graph Learning for Heart Disease Prediction", "category": "research"}'::jsonb,
