INSERT INTO knowledge_base (content, source, source_type, metadata, embedding) VALUES
(
    'Built a T-9 style predictive formula entry system that maps phone keypad numbers to mathematical and Greek symbols (e.g., key 1 → +, v, θ; key 6 → Σ, α, β) for fast equation input in text editors (BITS F364 Human Computer Interaction course project, April 2024, Dr. Mukesh Kumar Rohil). T-9 (Text on 9 keys) is a predictive text input method originally used on phone keypads.',
    'hci_project',
    'project',
    '{"project": "T-9 Style Predictive Formula Entry System", "category": "coursework"}'::jsonb,
