INSERT INTO knowledge_base (content, source, source_type, metadata, embedding) VALUES
(
    'Implementing IVF-PQ (Inverted File Index with Product Quantization) GPU-accelerated approximate nearest neighbor (ANN) search engine in CUDA C/C++ — the same core algorithm used by production vector databases FAISS, Milvus, and Pinecone for billion-scale vector similarity search (ME/CS/ECE 759 High Performance Computing, Spring 2026). ANN search is the backbone of RAG pipelines, recommendation systems, and image retrieval.',
