INSERT INTO knowledge_base (content, source, source_type, metadata, embedding) VALUES
(
    'Implemented a full LL(1) predictive parser with automated FIRST/FOLLOW set computation (ComputeFirstandFollowSets()), a 52-non-terminal × 57-terminal parse table, parse tree generation with parent/child/count node structure, and synch-based error recovery (CS F363 Compiler Construction, BITS Pilani, 2024). LL(1) parsing is a top-down parsing strategy that reads input left-to-right using 1 token lookahead — the basis for many production compilers.',
    'compiler_project',
    'project',
    '{"project": "Compiler Frontend \u2014 Lexer and Parser", "category": "coursework"}'::jsonb,
