INSERT INTO knowledge_base (content, source, source_type, metadata, embedding) VALUES
(
    'Built a multi-type flashcard study application in Java + JavaFX (Java''s GUI framework) supporting four card formats: MCQ (Multiple Choice Question), True/False, Fill-in-the-Blank (FIB), and Definition — each implemented as a distinct subclass extending a shared abstract Card base class (FlashCard Application, OOP coursework at BITS Pilani).',
    'flashcard_project',
